SELECT STOCK_DATE, MATERIAL_CODE, STOCK_NUM, AVAILABLE_STOCK, DATA_VERSION FROM T_MES_CD90_STOCK WHERE IS_DELETE = 0 AND CONVERT(DATE, STOCK_DATE) = CONVERT(DATE, #{stockDate})
AND DATA_VERSION = #{dataVersion}
AND DATA_VERSION = ( SELECT MAX(DATA_VERSION) FROM T_MES_CD90_STOCK WHERE IS_DELETE = 0 AND CONVERT(DATE, STOCK_DATE) = CONVERT(DATE, #{stockDate}) )

SELECT FACTORY_CODE, LANE_DATE, SHIFT_CODE, STORAGE_LANE_CODE, MATERIAL_CODE, CAR_NUM, MAX_CAR_NUM, AVAILABLE_CAR_NUM FROM T_MES_CD90_STORAGE_LANE_LIMIT WHERE IS_DELETE = 0 AND LANE_DATE IS NOT NULL AND SHIFT_CODE IS NOT NULL AND STORAGE_LANE_CODE IS NOT NULL AND FACTORY_CODE = #{factoryCode}
AND DATA_VERSION = #{dataVersion}
AND DATA_VERSION = ( SELECT MAX(DATA_VERSION) FROM T_MES_CD90_STORAGE_LANE_LIMIT WHERE IS_DELETE = 0 AND FACTORY_CODE = #{factoryCode} )
